CREATE TYPE project_status AS ENUM ('draft','queued','processing','composing','completed','failed','cancelled');
CREATE TYPE member_role AS ENUM ('owner','admin','member');
CREATE TABLE users (id text PRIMARY KEY,email text UNIQUE NOT NULL,name text NOT NULL,password_hash text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE organizations (id text PRIMARY KEY,name text NOT NULL,vertical text NOT NULL DEFAULT 'real_estate',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE organization_members (organization_id text REFERENCES organizations(id) ON DELETE CASCADE,user_id text REFERENCES users(id) ON DELETE CASCADE,role member_role NOT NULL DEFAULT 'member',PRIMARY KEY(organization_id,user_id));
CREATE TABLE brand_kits (id text PRIMARY KEY,organization_id text UNIQUE NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,logo_url text,primary_color text DEFAULT '#6957df',secondary_color text DEFAULT '#172033',website text,phone text,social_handle text,created_at timestamptz DEFAULT now(),updated_at timestamptz DEFAULT now());
CREATE TABLE vertical_definitions (id text PRIMARY KEY,slug text NOT NULL,name text NOT NULL,version int NOT NULL,form_schema jsonb NOT NULL,active boolean NOT NULL DEFAULT true,created_at timestamptz DEFAULT now(),updated_at timestamptz DEFAULT now(),UNIQUE(slug,version));
CREATE TABLE video_templates (id text PRIMARY KEY,vertical text NOT NULL,slug text UNIQUE NOT NULL,name text NOT NULL,description text,thumbnail_url text,configuration jsonb NOT NULL,active boolean DEFAULT true,created_at timestamptz DEFAULT now(),updated_at timestamptz DEFAULT now());
CREATE TABLE video_projects (id text PRIMARY KEY,organization_id text NOT NULL REFERENCES organizations(id),user_id text NOT NULL REFERENCES users(id),vertical text NOT NULL,objective text NOT NULL,title text NOT NULL,status project_status NOT NULL DEFAULT 'draft',input_data jsonb NOT NULL,render_plan jsonb,template_id text REFERENCES video_templates(id),aspect_ratio text NOT NULL DEFAULT '9:16',duration_seconds int NOT NULL DEFAULT 30,output_url text,thumbnail_url text,error_message text,estimated_cost numeric,actual_cost numeric,created_at timestamptz DEFAULT now(),updated_at timestamptz DEFAULT now());
CREATE TABLE media_assets (id text PRIMARY KEY,project_id text NOT NULL REFERENCES video_projects(id) ON DELETE CASCADE,storage_key text NOT NULL,url text NOT NULL,media_type text NOT NULL,label text,position int NOT NULL,metadata jsonb NOT NULL DEFAULT '{}',created_at timestamptz DEFAULT now());
CREATE TABLE generation_jobs (id text PRIMARY KEY,project_id text NOT NULL REFERENCES video_projects(id) ON DELETE CASCADE,provider text NOT NULL,provider_prediction_id text,job_type text NOT NULL,status project_status NOT NULL,input jsonb NOT NULL,output jsonb,error_message text,webhook_event_id text UNIQUE,started_at timestamptz,completed_at timestamptz,created_at timestamptz DEFAULT now(),updated_at timestamptz DEFAULT now());
CREATE TABLE credit_accounts (organization_id text PRIMARY KEY REFERENCES organizations(id),balance int NOT NULL DEFAULT 100,updated_at timestamptz DEFAULT now());
